    HTTP.register!(router, "GET", path_prefix * "/system/console/status-productinfo.json", OpenAPI.Servers.middleware(impl, get_aem_product_info_read, get_aem_product_info_validate, get_aem_product_info_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/system/console/bundles/{name}.json", OpenAPI.Servers.middleware(impl, get_bundle_info_read, get_bundle_info_validate, get_bundle_info_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/system/console/configMgr", OpenAPI.Servers.middleware(impl, get_config_mgr_read, get_config_mgr_validate, get_config_mgr_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/system/console/bundles/{name}", OpenAPI.Servers.middleware(impl, post_bundle_read, post_bundle_validate, post_bundle_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/system/console/jmx/com.adobe.granite:type=Repository/op/{action}", OpenAPI.Servers.middleware(impl, post_jmx_repository_read, post_jmx_repository_validate, post_jmx_repository_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/system/console/configMgr/com.adobe.granite.auth.saml.SamlAuthenticationHandler", OpenAPI.Servers.middleware(impl, post_saml_configuration_read, post_saml_configuration_validate, post_saml_configuration_invoke; optional_middlewares...))
    return router
end
